    public static function updateProcess($request, $processId, $usuario_id)
    {
        $process = BpmnProcessPeer::retrieveByPK($processId);
        $forceNewVersion = $request->getParameter('force_new_version', false);
        $newBpmnXml = $request->getParameter('bpmn_xml');

        if (!$process) {
            return 404;
        }

        // Actualizar campos si vienen en el request
        if ($request->hasParameter('name')) {
        	$name = $request->getParameter('name');
        } else {
            $name = $process->getNombre();
        }

        if ($request->hasParameter('description')) {
            $description = $request->getParameter('description');
        } else {
            $description = $process->getDescripcion();
        }

        if ($request->hasParameter('is_active')) {
            $old_process = clone $process;

            $process->setIsActive((bool) $request->getParameter('is_active'));
            $process->setFechaModificacion(date("Y-m-d G:i:s"));
            $process->save();

            AuditLogPeer::guardarAuditoriaLite(
                BpmnProcessPeer::getOMClass(),
                $old_process,
                $process,
                ModulesEnable::Seguridad,
                $process->getNombre(),
                $usuario_id
            );

            return [
                'success' => true,
                'process_id' => $process->getPrimaryKey(),
                'version' => $process->getVersion(),
                'message' => 'Proceso actualizado correctamente'
            ];
        } else {
            // Usar el manager para guardar
            $result = BpmnProcessManager::saveProcess(
                $processId,
                $name,
                $description,
                $newBpmnXml,
                $usuario_id,
                (bool)$forceNewVersion
            );
        }

        if (!$result['success']) {
            throw new Exception($result['message']);
        }

        $process = $result['process'];

        return [
            'success' => true,
            'process_id' => $process->getPrimaryKey(),
            'version' => $process->getVersion(),
            'is_new_version' => $result['is_new_version'],
            'message' => $result['message']
        ];

        $versionIncremented = false;

        // Actualizar campos si vienen en el request
        if ($request->hasParameter('name')) {
            $process->setNombre($request->getParameter('name'));
        }

        if ($request->hasParameter('description')) {
            $process->setDescripcion($request->getParameter('description'));
        }

        if ($request->hasParameter('bpmn_xml')) {
            $oldBpmnXml = $process->getBpmnXml();
            $newBpmnXml = $request->getParameter('bpmn_xml');

            // Solo incrementar versión si el XML cambió
            if ($oldBpmnXml !== $newBpmnXml) {
                $changes = self::generateChangelog($oldBpmnXml, $newBpmnXml);
                // Opcional: Guardar versión anterior en tabla de historial
                self::archiveProcessVersion($process, $usuario_id, json_encode($changes));
                // Incrementar versión
                $process->setVersion($process->getVersion() + 1);
                $versionIncremented = true;
            }

            $process->setBpmnXml($newBpmnXml);
            $process->setFechaModificacion(date("Y-m-d G:i:s"));

            // Re-parsear y actualizar definiciones
            self::parseAndCreateTaskDefinitions($process);
        }

        if ($request->hasParameter('is_active')) {
            $process->setIsActive((bool) $request->getParameter('is_active'));
        }

        $process->save();

        $message = 'Proceso actualizado correctamente';
        if ($versionIncremented) {
            $message .= ' (Nueva versión: ' . $process->getVersion() . ')';
        }

        return [
            'success' => true,
            'message' => $message,
            'version' => $process->getVersion()
        ];
    }

    public static function createProcess($request, $usuario_id)
    {
        $processId = $request->getParameter('process_id');
        $name = $request->getParameter('name');
        $description = $request->getParameter('description', '');
        $bpmnXml = $request->getParameter('bpmn_xml');
        $forceNewVersion = $request->getParameter('force_new_version', false);

        if (empty($name) || empty($bpmnXml)) {
            throw new Exception('Nombre y XML BPMN son requeridos');
        }
        try {
            // Usar el manager para guardar
            $result = BpmnProcessManager::saveProcess(
                $processId ? (int)$processId : null,
                $name,
                $description,
                $bpmnXml,
                $usuario_id,
                (bool)$forceNewVersion
            );

            if (!$result['success']) {
                throw new Exception($result['message']);
            }

            $process = $result['process'];

            return [
                'success' => true,
                'process_id' => $process->getPrimaryKey(),
                'version' => $process->getVersion(),
                'is_new_version' => $result['is_new_version'],
                'message' => $result['message']
            ];
        } catch (PropelException $th) {
            TaskDefinitionPeer::doDelete($process->getPrimaryKey());
            WorkflowConfigurationPeer::doDelete($process->getPrimaryKey());
            $process->delete();
        } catch (\Exception $th) {
            TaskDefinitionPeer::doDelete($process->getPrimaryKey());
            WorkflowConfigurationPeer::doDelete($process->getPrimaryKey());
            $process->delete();
        } catch (\Throwable $th) {
            TaskDefinitionPeer::doDelete($process->getPrimaryKey());
            WorkflowConfigurationPeer::doDelete($process->getPrimaryKey());
            $process->delete();
        }

        return [
            'success' => false,
            'message' => 'Error al crear el proceso'
        ];
    }

    public static function parseAndCreateTaskDefinitions($process)
    {
        $dom = new DOMDocument();
        $dom->loadXML($process->getBpmnXml());

        // Eliminar definiciones anteriores
        $c = new Criteria();
        $c->add(TaskDefinitionPeer::BPMNPROCESS_ID, $process->getPrimaryKey());
        TaskDefinitionPeer::doDelete($c);

        // Crear definiciones para user tasks
        $userTasks = $dom->getElementsByTagName('userTask');
        foreach ($userTasks as $task) {
            $taskDef = new TaskDefinition();
            $taskDef->setBpmnProcessId($process->getPrimaryKey());
            $taskDef->setTaskId($task->getAttribute('id'));
            $taskDef->setTaskName($task->getAttribute('name') ?: $task->getAttribute('id'));
            $taskDef->setTaskType('userTask');

            // Extraer assignee si está definido
            $assignee = $task->getAttribute('assignee');
            if (empty($assignee)) {
                $assignee = $task->getAttributeNS('http://camunda.org/schema/1.0/bpmn', 'assignee');
            }

            if ($assignee) {
                if (is_numeric($assignee)) {
                    $taskDef->setAssigneeType('user');
                    $taskDef->setAssigneeValue($assignee);
                } elseif (strpos($assignee, '${') !== false) {
                    $taskDef->setAssigneeType('expression');
                    $taskDef->setAssigneeValue($assignee);
                } else {
                    $taskDef->setAssigneeType('role');
                    $taskDef->setAssigneeValue($assignee);
                }
            }

            $taskConfigAttr = $task->getAttribute('custom:taskConfig');
            if (empty($taskConfigAttr)) {
                $taskConfigAttr = $task->getAttributeNS('http://custom', 'taskConfig');
            }

            if (!empty($taskConfigAttr)) {
                // Decodificar JSON
                $configData = json_decode($taskConfigAttr, true);

                if ($configData && is_array($configData)) {
                    // Guardar campos del formulario
                    if (isset($configData['formFields']) && !empty($configData['formFields'])) {
                        $taskDef->setFormData(json_encode(['fields' => $configData['formFields']]));
                    }

                    // Guardar duraciones
                    if (isset($configData['durationExpected'])) {
                        $taskDef->setDurationExpected((int)$configData['durationExpected']);
                    }
                    if (isset($configData['durationMax'])) {
                        $taskDef->setDurationMax((int)$configData['durationMax']);
                    }

                    // Actualizar tipo de asignación si está en config y no hay assignee
                    if (isset($configData['assigneeType']) && empty($assignee)) {
                        $taskDef->setAssigneeType($configData['assigneeType']);
                    }
                }
            } else {
                // Extraer variables del formulario desde extensionElements
                $extensionElements = $task->getElementsByTagName('extensionElements');
                if ($extensionElements->length > 0) {
                    $formFields = self::extractFormFields($extensionElements->item(0));
                    if (!empty($formFields)) {
                        $taskDef->setFormData(json_encode(['fields' => $formFields]));
                    }

                    // Extraer propiedades de duración
                    $properties =  self::extractProperties($extensionElements->item(0));
                    if (isset($properties['durationExpected'])) {
                        $taskDef->setDurationExpected((int)$properties['durationExpected']);
                    }
                    if (isset($properties['durationMax'])) {
                        $taskDef->setDurationMax((int)$properties['durationMax']);
                    }
                }
            }

            $taskDef->setFechaCreacion(date('Y-m-d G:i:s'));
            $taskDef->setFechaModificacion(date('Y-m-d G:i:s'));
            $taskDef->setIsActive(true);
            $taskDef->save();
        }

        // Crear configuraciones de flujos
        self::createFlowConfigurations($process, $dom);
    }

    /**
     * Extrae campos del formulario desde extensionElements
     */
    public static function extractFormFields($extensionElements)
    {
        $formFields = [];

        // Buscar camunda:FormData
        $formDataList = $extensionElements->getElementsByTagName('formData');

        foreach ($formDataList as $formData) {
            $fields = $formData->getElementsByTagName('formField');

            foreach ($fields as $field) {
                $formFields[] = [
                    'id' => $field->getAttribute('id'),
                    'label' => $field->getAttribute('label'),
                    'type' => $field->getAttribute('type') ?: 'string',
                    'defaultValue' => $field->getAttribute('defaultValue') ?: '',
                    'required' => $field->getAttribute('required') === 'true'
                ];
            }
        }

        return $formFields;
    }

    /**
     * Extrae propiedades personalizadas
     */
    public static function extractProperties($extensionElements)
    {
        $properties = [];

        $propertiesList = $extensionElements->getElementsByTagName('properties');

        foreach ($propertiesList as $props) {
            $propertyNodes = $props->getElementsByTagName('property');

            foreach ($propertyNodes as $prop) {
                $name = $prop->getAttribute('name');
                $value = $prop->getAttribute('value');
                if ($name) {
                    $properties[$name] = $value;
                }
            }
        }

        return $properties;
    }

    public static function createFlowConfigurations($process, $dom)
    {
        // Eliminar configuraciones anteriores
        $c = new Criteria();
        $c->add(WorkflowConfigurationPeer::BPMNPROCESS_ID, $process->getPrimaryKey());
        WorkflowConfigurationPeer::doDelete($c);

        $sequenceFlows = $dom->getElementsByTagName('sequenceFlow');
        foreach ($sequenceFlows as $flow) {
            $flowConfig = new WorkflowConfiguration();
            $flowConfig->setBpmnProcessId($process->getPrimaryKey());
            $flowConfig->setWorkflowId($flow->getAttribute('id'));
            $flowConfig->setSourceRef($flow->getAttribute('sourceRef'));
            $flowConfig->setTargetRef($flow->getAttribute('targetRef'));

            $condition = $flow->getAttribute('conditionExpression');
            if ($condition) {
                $flowConfig->setConditionExpression($condition);
            }

            $flowConfig->setFechaCreacion(date('Y-m-d G:i:s'));
            $flowConfig->setFechaModificacion(date('Y-m-d G:i:s'));
            $flowConfig->setIsActive(true);
            $flowConfig->save();
        }
    }

