    /**
     * Archiva la versión anterior del proceso (opcional)
     */
    public static function archiveProcessVersion($process, $usuario_id, $changes)
    {
        try {
            $archive = new BpmnVersionHistory();
            $archive->setBpmnProcessId($process->getPrimaryKey());
            $archive->setUsuarioId($usuario_id);
            $archive->setVersion($process->getVersion());
            $archive->setBpmnXml($process->getBpmnXml());
            $archive->setChangesSummary($changes);
            $archive->setFechaArchivado(date("Y-m-d G:i:s"));
            $archive->setFechaCreacion(date("Y-m-d G:i:s"));
            $archive->save();
        } catch (PropelException $e) {
            return 500;
        } catch (Exception $e) {
            return 500;
        }
    }

    public static function deleteProcess($processId)
    {
        $process = BpmnProcessPeer::retrieveByPK($processId);

        if (!$process) {
            return 404;
        }

        // Verificar si hay instancias activas
        $c = new Criteria();
        $c->add(WorkflowInstancePeer::BPMNPROCESS_ID, $processId);
        $c->add(WorkflowInstancePeer::WORKFLOWSTATUS_ID, [WorkflowInstanceStatusBpmn::running, WorkflowInstanceStatusBpmn::suspended], Criteria::IN);
        $activeInstances = WorkflowInstancePeer::doCount($c);

        if ($activeInstances > 0) {
            return [
                'success' => false,
                'message' => "No se puede eliminar el proceso porque tiene $activeInstances instancia(s) activa(s)"
            ];
        }

        $process->delete();

        return [
            'success' => true,
            'message' => 'Proceso eliminado correctamente'
        ];
    }

    public static function generateChangelog($oldXml, $newXml)
    {
        $oldParser = new BpmnParser($oldXml);
        $newParser = new BpmnParser($newXml);

        $oldTasks = $oldParser->getUserTasks();
        $newTasks = $newParser->getUserTasks();

        $changes = [
            'added' => array_diff($newTasks, $oldTasks),
            'removed' => array_diff($oldTasks, $newTasks)
        ];

        return $changes;
    }

    /**
     * Procesa archivos subidos en una tarea
     */
    public static function processTaskAttachments($taskId, $request)
    {
        $usuariologuiado = sfContext::getInstance()->getUser()->getAttribute('usuario_id', '', 'subscriber');
        $task = TaskInstancePeer::retrieveByPK($taskId);
        if (!$task) {
            throw new Exception('Tarea no encontrada');
        }

        $attachmentIds = [];
        $storage_info =  TaskAttachmentPeer::getTaskBpmnAttachmentStorage($task->getRegionalId());
        $uploadDir = $storage_info['path_target'] . DIRECTORY_SEPARATOR . date("Y-m-d");

        // Crear directorio si no existe
        if (!is_dir($uploadDir)) {
            throw new Exception('Directorio de subida no encontrado');
        }

        // Procesar cada archivo
        foreach ($request->getFiles() as $fieldName => $file) {
            if ($file && $file['error'] === UPLOAD_ERR_OK) {
                // Generar nombre único
                $extension = pathinfo($file['name'], PATHINFO_EXTENSION);
                $filename = uniqid() . '_' . time() . '.' . $extension;
                $relativePath = 'workflow_attachments/' . $filename;
                $fullPath = sfConfig::get('sf_upload_dir') . '/' . $relativePath;

                // Mover archivo
                if (move_uploaded_file($file['tmp_name'], $fullPath)) {
                    // Crear registro en BD
                    $attachment = new TaskAttachment();
                    $attachment->setTaskInstanceId($taskId);
                    $attachment->setWorkflowInstanceId($task->getWorkflowInstanceId());
                    $attachment->setFilename($filename);
                    $attachment->setOriginalFilename($file['name']);
                    $attachment->setFilePath($relativePath);
                    $attachment->setFileSize($file['size']);
                    $attachment->setMimeType($file['type']);
                    $attachment->setUploadedBy($usuariologuiado);

                    // Determinar si es público (parámetro opcional)
                    $isPublic = $request->getParameter('is_public_' . $fieldName, true);
                    $attachment->setIsPublic($isPublic);

                    $description = $request->getParameter('description_' . $fieldName, '');
                    if ($description) {
                        $attachment->setDescription($description);
                    }

                    $attachment->save();

                    $attachmentIds[] = [
                        'id' => $attachment->getPrimaryKey(),
                        'filename' => $file['name'],
                        'size' => $file['size']
                    ];
                }
            }
        }

        return $attachmentIds;
    }

